import heapq

def solve(nums, k):
    # Use a max-heap of size k to keep the k smallest elements
    # Since Python's heapq is a min-heap, we store negatives to simulate a max-heap
    heap = []
    for num in nums:
        if len(heap) < k:
            heapq.heappush(heap, -num)
        else:
            if -heap[0] > num:
                heapq.heappop(heap)
                heapq.heappush(heap, -num)
    return -heap[0]
