import heapq

def solve(nums, k):
    # Create a max heap of size k
    heap = []
    for num in nums:
        # If the heap has less than k elements, push the current number
        if len(heap) < k:
            heapq.heappush(heap, -num)
        else:
            # If the current number is smaller than the largest in the heap, replace it
            if num < -heap[0]:
                heapq.heappushpop(heap, -num)
    # The root of the heap is the k-th smallest element
    return -heap[0]
