def solve(nums, k):
    def quickselect(start, end, k):
        if start == end:
            return nums[start]
        pivot = nums[end]
        left = start
        right = end - 1
        while left <= right:
            if nums[left] < pivot:
                left += 1
            elif nums[right] > pivot:
                right -= 1
            else:
                nums[left], nums[right] = nums[right], nums[left]
                left += 1
                right -= 1
        nums[left], nums[end] = nums[end], nums[left]
        if k == left:
            return pivot
        elif k < left:
            return quickselect(start, left - 1, k)
        else:
            return quickselect(left + 1, end, k)
    return quickselect(0, len(nums) - 1, k)
