def solve(nums):
    def find_intersection():
        tortoise = nums[0]
        hare = nums[0]
        while True:
            tortoise = nums[tortoise]
            hare = nums[nums[hare]]
            if tortoise == hare:
                break
        return tortoise

    def find_cycle_start(intersection):
        pointer1 = nums[0]
        pointer2 = intersection
        while pointer1 != pointer2:
            pointer1 = nums[pointer1]
            pointer2 = nums[pointer2]
        return pointer1

    intersection = find_intersection()
    return find_cycle_start(intersection)
```

