    # Floyd's cycle detection algorithm
    def find_cycle_start():
        tortoise = nums[0]
        hare = nums[0]
        # Phase 1: Find intersection point of tortoise and hare
        while True:
            tortoise = nums[tortoise]
            hare = nums[nums[hare]]
            if tortoise == hare:
                break
        # Phase 2: Find the start of the cycle
        tortoise = nums[0]
        while tortoise != hare:
            tortoise = nums[tortoise]
            hare = nums[hare]
        return hare

    return find_cycle_start()
