def solve(nums):
    def count_less_equal(mid):
        count = 0
        for num in nums:
            if num <= mid:
                count += 1
        return count

    low, high = 1, len(nums)
    while low < high:
        mid = (low + high) // 2
        if count_less_equal(mid) > mid:
            low = mid + 1
        else:
            high = mid
    return low
