from collections import Counter

def solve(nums, k):
    freq = Counter(nums)
    # Bucket sort by frequency
    buckets = {}
    for num, count in freq.items():
        if count not in buckets:
            buckets[count] = []
        buckets[count].append(num)
    # Get the frequencies in descending order
    sorted_freq = sorted(freq.values(), reverse=True)
    # Find the k-th frequency
    target_freq = sorted_freq[k-1]
    # Collect all numbers with frequency >= target_freq
    result = []
    for freq_val in sorted_freq:
        if freq_val == target_freq:
            result.extend(buckets[freq_val])
        elif freq_val > target_freq:
            result.extend(buckets[freq_val])
        else:
            break
    return result
```

