    counts = Counter(nums)
    unique_nums = list(counts.keys())
    counts_list = list(counts.values())

    def select(k, counts_list, unique_nums):
        if k == 1:
            return [unique_nums[0]]
        pivot = counts_list[len(counts_list) // 2]
        left = [x for x in counts_list if x > pivot]
        right = [x for x in counts_list if x < pivot]
        equal = [x for x in counts_list if x == pivot]
        left_nums = [unique_nums[i] for i in range(len(counts_list)) if counts_list[i] > pivot]
        right_nums = [unique_nums[i] for i in range(len(counts_list)) if counts_list[i] < pivot]
        equal_nums = [unique_nums[i] for i in range(len(counts_list)) if counts_list[i] == pivot]

        if k <= len(left):
            return select(k, left, left_nums)
        elif k <= len(left) + len(equal):
            return equal_nums
        else:
            return select(k - len(left) - len(equal), right, right_nums)

    return select(k, counts_list, unique_nums)
