from collections import Counter

def solve(nums, k):
    counts = Counter(nums)
    keys = list(counts.keys())
    values = list(counts.values())

    def partition(arr, l, r, pivot_idx):
        pivot = arr[pivot_idx]
        arr[pivot_idx], arr[r] = arr[r], arr[pivot_idx]
        store_idx = l
        for i in range(l, r):
            if arr[i] > pivot:
                arr[store_idx], arr[i] = arr[i], arr[store_idx]
                store_idx += 1
        arr[store_idx], arr[r] = arr[r], arr[store_idx]
        return store_idx

    def quickselect(arr, l, r, k):
        if l == r:
            return arr[l]
        pivot_idx = l + (r - l) // 2
        pivot_idx = partition(arr, l, r, pivot_idx)
        if k == pivot_idx:
            return arr[k]
        elif k < pivot_idx:
            return quickselect(arr, l, pivot_idx - 1, k)
        else:
            return quickselect(arr, pivot_idx + 1, r, k)

    # Get the k-th highest frequency
    target_freq = quickselect(values, 0, len(values) - 1, len(values) - k)

    # Find all keys with that frequency
    result = [key for key in keys if counts[key] == target_freq]
    return result
