import random

def solve(nums, k):
    counts = Counter(nums)
    unique_nums = list(counts.keys())
    n = len(unique_nums)

    def quickselect(arr, k, counts):
        if len(arr) == 1:
            return arr[0]

        pivot = random.choice(arr)
        left = [x for x in arr if counts[x] > counts[pivot]]
        mid = [x for x in arr if counts[x] == counts[pivot]]
        right = [x for x in arr if counts[x] < counts[pivot]]

        if k <= len(left):
            return quickselect(left, k, counts)
        elif k <= len(left) + len(mid):
            return mid
        else:
            return quickselect(right, k - len(left) - len(mid), counts)

    pivot = quickselect(unique_nums, k, counts)
    freq = counts[pivot]

    result = [num for num in unique_nums if counts[num] == freq]

    return result
