    mod = 10**9 + 7

    def hash_string(s):
        hash_val = 0
        for c in s:
            hash_val = (hash_val * base + ord(c)) % mod
        return hash_val

    def get_prefix_hash(s, power):
        hash_val = 0
        for i in range(len(s)):
            hash_val = (hash_val * base + ord(s[i])) % mod
            if i < len(s) - 1:
                power[i + 1] = (power[i] * base) % mod
        return hash_val

    power = [1] * (len(haystack) + 1)
    for i in range(1, len(power)):
        power[i] = (power[i - 1] * base) % mod

    needle_hash = hash_string(needle)
    haystack_hash = get_prefix_hash(haystack, power)

    for i in range(len(haystack) - len(needle) + 1):
        current_hash = (haystack_hash - (power[len(needle)] * ord(haystack[i + len(needle) - 1])) % mod + mod) % mod
        current_hash = (current_hash * power[len(needle) - 1]) % mod
        if current_hash == needle_hash:
            return i

    return -1
