def solve(nums):
    # Compress the values to a smaller range
    sorted_unique = sorted(set(nums))
    compression = {v: i+1 for i, v in enumerate(sorted_unique)}
    compressed = [compression[num] for num in nums]

    # Fenwick Tree implementation
    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 1)

        def update(self, index, value):
            while index <= self.n:
                self.tree[index] = max(self.tree[index], value)
                index += index & -index

        def query(self, index):
            res = 0
            while index > 0:
                res = max(res, self.tree[index])
                index -= index & -index
            return res

    ft = FenwickTree(len(sorted_unique))
    max_length = 0
    for num in reversed(compressed):
        length = ft.query(num - 1) + 1
        ft.update(num, length)
        max_length = max(max_length, length)
    return max_length
