def solve(intervals):
    if not intervals:
        return []

    # Create a union-find structure for all unique points
    points = set()
    for start, end in intervals:
        points.add(start)
        points.add(end)

    # Convert points to a sorted list and map to indices for union-find
    sorted_points = sorted(points)
    point_to_index = {p: i for i, p in enumerate(sorted_points)}
    parent = list(range(len(sorted_points)))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        parent[find(u)] = find(v)

    # Process intervals to merge overlapping or touching ones
    for start, end in intervals:
        s = point_to_index[start]
        e = point_to_index[end]
        union(s, e)

    # Group points by their root parent
    groups = {}
    for i in range(len(sorted_points)):
        root = find(i)
        if root not in groups:
            groups[root] = []
        groups[root].append(sorted_points[i])

    # Convert groups to merged intervals
    merged = []
    for group in groups.values():
        merged.append([group[0], group[-1]])

    # Sort merged intervals by start
    merged.sort()
    return merged
