    if not intervals:
        return []

    # Union-Find (Disjoint Set Union) data structure
    parent = {}
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        parent[find(x)] = find(y)

    # Map each interval to a unique identifier
    # We'll use the start and end points as keys to track which intervals are connected
    # Since intervals can have same start and end, we'll use tuples to uniquely identify them
    interval_ids = {}
    id = 0
    for start, end in intervals:
        interval_ids[(start, end)] = id
