        return 0

    # Sort intervals by end time
    intervals.sort(key=lambda x: x[1])

    # Dynamic programming with binary search
    dp = []
    for interval in intervals:
        start, end = interval
        # Binary search for the largest index where end <= start
        left, right = 0, len(dp) - 1
        idx = -1
        while left <= right:
            mid = (left + right) // 2
            if dp[mid][1] <= start:
                idx = mid
                left = mid + 1
            else:
                right = mid - 1

        if idx == -1:
            # No non-overlapping interval found, add this one
            dp.append(interval)
        else:
            # Replace the one with the earliest end time that can be replaced
            dp[idx] = interval

