def solve(n, edges):
    def bfs(start, adj):
        visited = [False] * n
        queue = deque()
        queue.append((start, -1))  # (current node, parent)
        visited[start] = True
        while queue:
            node, parent = queue.popleft()
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append((neighbor, node))
                elif neighbor != parent:
                    return True
        return False

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        if not bfs(i, adj):
            continue
        else:
            return True
    return False
