def solve(n, edges):
    from collections import defaultdict

    def count_edges(component):
        return len(edges) - sum(1 for u, v in edges if u in component or v in component)

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    components = []

    def dfs(node, current_component):
        visited[node] = True
        current_component.append(node)
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, current_component)

    for i in range(n):
        if not visited[i]:
            current_component = []
            dfs(i, current_component)
            components.append(current_component)

    for component in components:
        m = len(component)
        edge_count = count_edges(component)
        if m > 1 and edge_count >= m:
            return True

    return False
