def solve(nums, target):
    def binary_search(left, right):
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            elif nums[mid] > target:
                right = mid - 1
            else:
                return mid
        return -1

    if not nums:
        return [-1, -1]

    # Find the first element >= target using exponential search
    n = len(nums)
    first = 0
    while first < n and nums[first] < target:
        first *= 2

    # Binary search between [first // 2, first]
    left, right = max(0, first // 2), first
    idx = binary_search(left, right)

    if idx == -1:
        return [-1, -1]

    # Find the first occurrence
    left, right = 0, idx
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target and (mid == 0 or nums[mid - 1] != target):
            first_idx = mid
            break
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    else:
        first_idx = -1

    # Find the last occurrence
    left, right = idx, n - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target and (mid == n - 1 or nums[mid + 1] != target):
            last_idx = mid
            break
        elif nums[mid] > target:
            right = mid - 1
        else:
            left = mid + 1
    else:
        last_idx = -1

    return [first_idx, last_idx]
