def solve(nums, k):
    # Count frequency of each number
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    # Find all unique numbers and sort them
    sorted_nums = sorted(freq.keys())

    # Count cumulative frequencies to find the k-th smallest
    count = 0
    for num in sorted_nums:
        count += freq[num]
        if count >= k:
            return num
