from collections import Counter

def solve(nums, k):
    counts = Counter(nums)
    freq_buckets = {}
    for num, freq in counts.items():
        if freq not in freq_buckets:
            freq_buckets[freq] = []
        freq_buckets[freq].append(num)

    sorted_freqs = sorted(freq_buckets.keys(), reverse=True)
    for freq in sorted_freqs:
        if len(freq_buckets[freq]) >= k:
            return freq_buckets[freq][:k]
