                self.max_end = max(self.max_end, new_end)

        def merge(self, new_start, new_end):
            if new_start <= self.max_end:
                self.start = min(self.start, new_start)
                self.end = max(self.end, new_end)
                if self.left and self.left.max_end >= new_start:
                    self.left.merge(new_start, new_end)
                if self.right and self.right.max_end >= new_start:
                    self.right.merge(new_start, new_end)
                self.max_end = max(self.max_end, new_end)
            else:
                if self.right is None:
                    self.right = IntervalNode(new_start, new_end)
                else:
                    self.right.insert(new_start, new_end)

    # Create root node
    root = IntervalNode(intervals[0][0], intervals[0][1])

    # Insert and merge intervals
    for start, end in intervals[1:]:
        root.merge(start, end)

    # Collect merged intervals in order
    result = []
    def traverse(node):
        if node:
            traverse(node.left)
            result.append([node.start, node.end])
            traverse(node.right)

