            queue.append(i)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != n:
        return []

    # Compute longest path depth from sources using topological sort
    depth = [0] * n
    visited = set()
    for node in result:
        if node not in visited:
            stack = [(node, 0)]
            visited.add(node)
            while stack:
                current, current_depth = stack.pop()
                depth[current] = max(depth[current], current_depth)
                for neighbor in graph[current]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append((neighbor, current_depth + 1))

    # Sort nodes by their depth
    result.sort(key=lambda x: depth[x])
