def solve(n, prerequisites):
    # Initialize in-degree array and adjacency list
    in_degree = [0] * n
    graph = [[] for _ in range(n)]

    for a, b in prerequisites:
        graph[b].append(a)
        in_degree[a] += 1

    result = []
    # Keep scanning until all nodes are processed or a cycle is detected
    while len(result) < n:
        found = False
        for i in range(n):
            if in_degree[i] == 0:
                # Remove this node from the graph
                result.append(i)
                for neighbor in graph[i]:
                    in_degree[neighbor] -= 1
                found = True
        if not found:
            return []
    return result
